#include "WorldHistory.hpp"
namespace elysium::history {static std::uint64_t mix(std::uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;x^=x>>31;return x?x:1;}StableId WorldHistory::deterministicId(std::uint64_t d,std::uint64_t a)const{return mix(seed_^mix(d)^mix(a)^version_);}bool WorldHistory::addCivilization(Civilization c,std::string&w){if(!c.id){w="invalid civilization";return false;}if(!civs_.emplace(c.id,std::move(c)).second){w="duplicate civilization";return false;}return true;}bool WorldHistory::append(HistoryEvent e,std::string&w){if(!e.id){w="invalid event";return false;}if(!events_.empty()&&e.epoch<events_.back().epoch){w="non-append epoch";return false;}for(auto&x:events_)if(x.id==e.id){w="event immutable/duplicate";return false;}events_.push_back(e);return true;}std::vector<HistoryEvent>WorldHistory::chronicleCandidates()const{std::vector<HistoryEvent>v;for(auto&e:events_)if(e.significant||e.type==HistoryEventType::PlayerSignificant)v.push_back(e);return v;}std::uint64_t WorldHistory::stableHash()const{std::uint64_t h=mix(seed_^version_);for(auto&e:events_)h=mix(h^e.id^std::uint64_t(e.type)^e.epoch^e.subject^e.object^e.site);return h;}}
